/*
 * Modified by Actuna Sp. z o.o.:
 *   FL-B-005: show and keep unknown layout values instead of removing them
 *   Z-14: no form rows unless editorTheme.flowLayout.enabled is set
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Form rows for editing the layout options of a flow (tab or subflow):
 *  - layout: where node ports are placed (LR, TB or auto)
 *  - wireStyle: how wires are drawn (curved or orthogonal)
 * An empty value means the editor default from the user settings is used.
 * An unknown value (for example from an imported flow) is shown as its own
 * option and kept unless the user selects another value.
 * The rows are only added when the flow layout functions are enabled
 * (editorTheme.flowLayout.enabled); otherwise the flow is left unchanged.
 */
RED.editor.flowLayout = (function() {

    function createSelect(container, id, label, icon, options, value) {
        const row = $('<div class="form-row"></div>').appendTo(container);
        $('<label>').attr("for", id).text(" " + label).prepend($('<i>').addClass("fa " + icon)).appendTo(row);
        const select = $('<select>').attr("id", id).css("width", "70%").appendTo(row);
        $('<option>').val("").text(RED._("layout.useDefault")).appendTo(select);
        options = RED.viewLayout.addUnknownOption(options, value, function(v) {
            return RED._("layout.unknownValue", { value: v });
        });
        options.forEach(function(o) {
            $('<option>').val(o.val).text(o.text).appendTo(select);
        });
        select.val(value ? String(value) : "");
        return select;
    }

    /**
     * Add the layout form rows
     * @param {JQuery} container the form to add the rows to
     * @param {object} flow the tab or subflow being edited
     */
    function create(container, flow) {
        if (!RED.viewLayout.isEnabled()) {
            return;
        }
        createSelect(container, "node-input-flow-layout", RED._("layout.flowLayout"), "fa-sitemap",
            RED.view.layout.layoutOptions(true), flow.layout);
        createSelect(container, "node-input-flow-wire-style", RED._("layout.wireStyle"), "fa-random",
            RED.view.layout.wireStyleOptions(), flow.wireStyle);
    }

    /**
     * Apply the form values to the flow, recording any changes in editState
     * @param {object} flow the tab or subflow being edited
     * @param {object} editState the edit state of the dialog
     */
    function apply(flow, editState) {
        let changed = false;
        if (!RED.viewLayout.isEnabled()) {
            return changed;
        }
        [["layout", "#node-input-flow-layout"], ["wireStyle", "#node-input-flow-wire-style"]].forEach(function(prop) {
            const input = $(prop[1]);
            if (input.length === 0) {
                return;
            }
            const value = input.val() || undefined;
            const current = flow[prop[0]] ? String(flow[prop[0]]) : undefined;
            if (current !== value) {
                editState.changes[prop[0]] = flow[prop[0]];
                editState.changed = true;
                if (value) {
                    flow[prop[0]] = value;
                } else {
                    delete flow[prop[0]];
                }
                changed = true;
            }
        });
        if (changed) {
            RED.view.redraw(true);
        }
        return changed;
    }

    return {
        create: create,
        apply: apply
    };
})();
